const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={companies:[],devices:[],logs:[],incidents:[],revision:0},view='Overview',company='All companies',query='',type='All types',busy=false;
async function api(path,method='GET',body){let r=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(r.status===401){location.href='/login';throw Error('Sign in required.')}let data=r.status===204?{}:await r.json();if(!r.ok)throw Error(data.error||'Request failed.');return data}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.add('hidden'),6500)}
function modal(html){$('#drawer').innerHTML='<button class="close" onclick="closePanel()" aria-label="Close">✕</button>'+html;$('#drawer').classList.remove('hidden')}
function closePanel(){$('#drawer').classList.add('hidden')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePanel()});
function ds(){return state.devices.filter(d=>company==='All companies'||d.company===company)}
function navigate(v){view=v;query='';type='All types';render()}
async function refresh(){state=await api('/api/state');if(company!=='All companies'&&!state.companies.includes(company))company='All companies';render()}
async function mutate(fn){if(busy)return toast('Please wait for the current save.');busy=true;let draft=structuredClone(state);try{fn(draft);state=await api('/api/state','PUT',draft);closePanel();render();toast('Saved to server.')}catch(e){toast(e.message);if(/another window/.test(e.message))await refresh()}finally{busy=false}}
function nav(){const items=['Overview','Devices','Companies','Alerts','Activity log','Settings'];$('#nav').innerHTML=items.map((v,i)=>`<button class="nav ${view===v?'active':''}" data-nav="${i}"><span>${['◫','▣','▦','♧','◷','⚙'][i]}</span>${v}</button>`).join('');document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(items[+el.dataset.nav]));$('#companynav').innerHTML=state.companies.map((c,i)=>`<div class="company" data-company="${i}"><span class="dot"></span>${esc(c)}</div>`).join('')||'<p class="metric-note">No companies yet</p>';document.querySelectorAll('[data-company]').forEach(el=>el.onclick=()=>{company=state.companies[+el.dataset.company];navigate('Overview')});$('#companyFilter').innerHTML=['All companies',...state.companies].map(c=>`<option ${company===c?'selected':''}>${esc(c)}</option>`).join('');$('#companyFilter').onchange=e=>{company=e.target.value;render()}}
function metric(v,suffix='%'){return v==null?'—':Number(v).toFixed(1)+suffix}
function age(t){if(!t)return 'Never reported';let seconds=Math.max(0,Math.round(Date.now()/1000-t));return seconds<60?seconds+'s ago':seconds<3600?Math.floor(seconds/60)+'m ago':Math.floor(seconds/3600)+'h ago'}
function duration(s){if(s==null)return '—';return Math.floor(s/86400)+'d '+Math.floor(s%86400/3600)+'h '+Math.floor(s%3600/60)+'m'}
function stats(){let devices=ds();return `<div class="stats">${[['Total devices',devices.length,'Across '+(company==='All companies'?state.companies.length:1)+' companies'],['Online',devices.filter(d=>['Online','Warning'].includes(d.status)).length,`Reporting within ${Math.round((state.monitoring?.rules.offlineSeconds??180)/60)} minutes`],['Active alerts',state.incidents.filter(i=>devices.some(d=>d.id===i.device)).length,'Open monitoring incidents'],['Awaiting data',devices.filter(d=>d.status==='Pending').length,'Connect a monitoring source']].map((s,i)=>`<div class="card stat"><span style="color:#7e899e">${s[0]}</span><div class="big ${i===1?'green':i===2?'amber':''}">${s[1]}</div><small>${s[2]}</small></div>`).join('')}</div>`}
function table(){return `<section class="card"><div class="cardhead"><h2>Devices</h2><span class="metric-note">${ds().length} total</span></div><div class="filters"><input id="search" class="search" aria-label="Search devices" placeholder="Search name, IP, or platform…" value="${esc(query)}"><select id="typeFilter" aria-label="Device type">${['All types','Server','Router','Switch','Storage','Access point','Printer'].map(t=>`<option ${type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="tablewrap"><table><thead><tr><th>DEVICE</th><th>STATUS</th><th>CPU / MEMORY</th><th>DISK / SUPPLIES</th><th>LAST REPORT</th></tr></thead><tbody id="rows"></tbody></table></div><div class="tablefoot">Select a device to view metrics, history, and connection settings.</div></section>`}
function supplySummary(d){let values=(d.supplies||[]).filter(s=>s.class===3&&s.percent!=null);return values.length?metric(Math.min(...values.map(s=>s.percent)))+' lowest':'Unavailable'}
function printerSupplies(d){if(d.integration?.kind!=='printer')return '';let threshold=d.integration.supplyThreshold??20;return `<h2 class="section">Printer supplies</h2><p class="metric-note">${threshold?'Warn at or below '+threshold+'% remaining':'Supply warnings disabled'}. Last report: ${age(d.lastSeen)}. ${d.status==='Offline'?'Readings are stale.':''}</p>${(d.supplies||[]).map(s=>`<div class="card"><strong>${esc(s.name)}</strong><p>${s.percent==null?'Unavailable':metric(s.percent)+' '+(s.class===4?'space remaining':'remaining')}</p>${s.percent==null?'':`<progress max="100" value="${Number(s.percent)}" aria-label="${esc(s.name)} remaining"></progress>`}</div>`).join('')||'<p class="empty">No supply readings yet. Poll the printer to discover cartridges.</p>'}`}
function rows(){let devices=ds().filter(d=>(type==='All types'||d.type===type)&&[d.name,d.ip,d.platform].join(' ').toLowerCase().includes(query.toLowerCase()));$('#rows').innerHTML=devices.map(d=>`<tr tabindex="0" role="button" data-device="${d.id}"><td><div class="device-name">${esc(d.name)}</div><div class="device-sub">${esc(d.ip)} · ${esc(d.platform)}</div></td><td><span class="badge ${d.status.toLowerCase()}">${esc(d.status)}</span></td><td>${metric(d.cpu)} / ${metric(d.memory)}</td><td>${d.integration?.kind==='printer'?supplySummary(d):metric(d.disk)}</td><td>${age(d.lastSeen)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No devices found. Add a company and device to begin.</td></tr>';document.querySelectorAll('[data-device]').forEach(el=>{el.onclick=()=>detail(+el.dataset.device);el.onkeydown=e=>{if(e.key==='Enter')el.click()}})}
function alerts(){let devices=ds(),items=state.incidents.filter(i=>devices.some(d=>d.id===i.device));return items.map(i=>{let d=devices.find(d=>d.id===i.device);return `<div class="alert"><span class="eventdot"></span><div><strong>${esc(i.message)}</strong><p>${esc(d.name)} · ${esc(d.company)}</p><small>Opened ${esc(new Date(i.opened*1000).toLocaleString())}</small></div></div>`}).join('')||'<div class="empty">No open incidents.</div>'}
function side(){return `<div class="right"><section class="card"><div class="cardhead"><h2>Needs attention</h2></div>${alerts()}</section><section class="card"><div class="cardhead"><h2>Monitoring</h2></div><div class="health"><p>Collect measurements from Linux agents, Proxmox, MikroTik, UniFi, or SNMPv3 connections.</p><p class="metric-note">Incidents follow the thresholds and missing-report timeout configured in Settings. Connection failures also open an incident. Recovery closes the incident automatically.</p></div></section></div>`}
function render(){nav();$('#breadcrumb').textContent=view;$('#title').textContent=view==='Overview'?'Infrastructure overview':view;$('#subtitle').textContent=({Overview:'Your infrastructure, in one clear view.',Devices:'Inventory and live agent measurements.',Companies:'Organize infrastructure by customer.',Alerts:'Current incidents and recovery history.','Activity log':'Server-recorded changes and monitoring events.',Settings:'Account, agent setup, and inventory backups.'})[view];$('#addDevice').onclick=()=>editDevice();let html='';if(view==='Overview')html=stats()+`<div class="grid">${table()}${side()}</div>`;if(view==='Devices')html=stats()+table();if(view==='Companies')html=`<button class="btn primary section" data-role="admin" onclick="editCompany()">＋ Add company</button><div class="companycards">${state.companies.map((c,i)=>`<section class="card"><h2>${esc(c)}</h2><p>${state.devices.filter(d=>d.company===c).length} devices</p><button class="btn" data-role="admin" data-edit-company="${i}">Edit company</button></section>`).join('')||'<div class="empty">No companies yet.</div>'}</div>`;if(view==='Alerts')html=`<div class="grid section"><section class="card"><div class="cardhead"><h2>Open incidents</h2></div>${alerts()}</section><section class="card"><div class="cardhead"><h2>Active monitoring rules</h2></div><div class="health"><p>Missing measurements: no report for ${state.monitoring?.rules.offlineSeconds??180} seconds, or API / SNMP connection failure.</p><p>Resource thresholds: CPU ${state.monitoring?.rules.cpu??90}%, memory ${state.monitoring?.rules.memory??90}%, disk ${state.monitoring?.rules.disk??90}%, temperature ${state.monitoring?.rules.temperature??70}°C.</p><p class="metric-note">Incidents are visible here and in the activity log. Notification channel: ${esc(state.monitoring?.delivery.mode||'none')}.</p><button class="btn" data-role="admin" onclick="monitoringForm()">Configure rules and delivery</button></div></section></div>`;if(view==='Activity log')html=`<section class="card section"><div class="cardhead"><h2>Activity</h2><button class="btn" onclick="exportLogs()">Export CSV</button></div><div class="tablewrap"><table><thead><tr><th>TIME</th><th>USER</th><th>ACTION</th><th>DEVICE / DETAIL</th></tr></thead><tbody>${state.logs.map(l=>`<tr><td>${esc(l.time)}</td><td>${esc(l.actor||'system')}</td><td>${esc(l.action)}</td><td>${esc(l.device)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No activity yet.</td></tr>'}</tbody></table></div></section>`;if(view==='Settings')html=`<div class="companycards"><section class="card" data-role="admin"><h2>Users and company access</h2><p>Create administrator, operator, and viewer accounts and assign company access.</p><button class="btn" onclick="usersForm()">Manage users</button></section><section class="card" data-role="admin"><h2>Monitoring and alerts</h2><p>Configure resource thresholds, missing-report timeouts, and Discord, SMTP email, or webhook delivery.</p><button class="btn" data-role="admin" onclick="monitoringForm()">Configure monitoring</button>${deliveryStatus()}</section><section class="card"><h2>Your account</h2><p>Change your sign-in password. Other sessions will be signed out.</p><button class="btn" onclick="passwordForm()">Change password</button></section><section class="card" data-role="admin"><h2>Inventory backup</h2><p>Export companies and inventory. Connection credentials and metric history stay on the server.</p><a class="btn" href="/api/backup">Download inventory</a><p><button class="btn" onclick="importInventory()">Import inventory</button></p></section><section class="card"><h2>Device integrations</h2><p>Open a device and select Connect agent to get its installation instructions. Each device has its own revocable credential.</p><p class="metric-note">Supported connections: Linux agent, Proxmox VE API, RouterOS 7 REST, official UniFi Network Integration API, and SNMPv3. Available management actions depend on the device and its permissions.</p></section></div>`;$('#page').innerHTML=html;if($('#rows')){rows();$('#search').oninput=e=>{query=e.target.value;rows()};$('#typeFilter').onchange=e=>{type=e.target.value;rows()}}document.querySelectorAll('[data-edit-company]').forEach(el=>el.onclick=()=>editCompany(+el.dataset.editCompany));applyRole()}
function editCompany(index=null){let old=index===null?'':state.companies[index];modal(`<h1>${old?'Edit':'Add'} company</h1><form id="companyForm"><label class="formlabel" for="companyName">Company name</label><input id="companyName" class="field" required maxlength="128" value="${esc(old)}"><div class="actions"><button class="btn primary">Save company</button>${old?'<button class="btn" type="button" id="deleteCompany">Delete company</button>':''}</div></form>`);$('#companyForm').onsubmit=e=>{e.preventDefault();let name=$('#companyName').value.trim();if(state.companies.some(c=>c!==old&&c.toLowerCase()===name.toLowerCase()))return toast('This company already exists.');mutate(s=>{if(old){s.companies[index]=name;s.devices.forEach(d=>{if(d.company===old)d.company=name})}else s.companies.push(name)})};if(old)$('#deleteCompany').onclick=()=>{if(state.devices.some(d=>d.company===old))return toast('Move or delete this company’s devices first.');if(confirm('Delete this company?'))mutate(s=>{s.companies.splice(index,1)})}}
function editDevice(id){if(!state.companies.length)return state.currentUser?.role==='admin'?editCompany():toast('Ask an administrator to assign a company to your account.');let d=state.devices.find(x=>x.id===id)||{name:'',company:company==='All companies'?state.companies[0]:company,type:'Server',ip:'',platform:'Ubuntu Linux',port:22};modal(`<h1>${id?'Edit':'Add'} device</h1><form id="deviceForm"><label class="formlabel" for="name">Device name</label><input id="name" class="field" name="name" required maxlength="128" value="${esc(d.name)}"><label for="deviceCompany">Company</label><select id="deviceCompany" class="field" name="company">${state.companies.map(c=>`<option ${d.company===c?'selected':''}>${esc(c)}</option>`).join('')}</select><label for="deviceType">Device type</label><select id="deviceType" class="field" name="type">${['Server','Router','Switch','Storage','Access point','Printer'].map(t=>`<option ${t===d.type?'selected':''}>${t}</option>`).join('')}</select><label for="ip">Management IP or hostname</label><input id="ip" class="field" name="ip" required maxlength="253" value="${esc(d.ip)}"><label for="platform">Platform / model</label><input id="platform" class="field" name="platform" required maxlength="128" value="${esc(d.platform)}"><label for="port">Connection check port</label><input id="port" class="field" name="port" type="number" min="1" max="65535" required value="${d.port||22}"><p class="metric-note">Inventory entries remain pending until their agent reports metrics.</p><button class="btn primary">Save device</button></form>`);$('#deviceForm').onsubmit=e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target));values.port=+values.port;mutate(s=>{if(id){Object.assign(s.devices.find(d=>d.id===id),values)}else{s.devices.push({...values,id:Date.now()})}})}}
async function detail(id){let d=state.devices.find(d=>d.id===id);if(!d)return;modal(`<span class="badge ${d.status.toLowerCase()}">${esc(d.status)}</span><h1 class="section">${esc(d.name)}</h1><p>${esc(d.company)} · ${esc(d.platform)}<br>${esc(d.ip)}</p>${d.integration?.kind==='printer'?'':`<div class="detailgrid">${[['CPU',metric(d.cpu)],['Memory',metric(d.memory)],['Disk',metric(d.disk)],['Temperature',metric(d.temp,'°C')],['Uptime',duration(d.uptimeSeconds)]].map(m=>`<div class="card"><small>${m[0]}</small><strong>${m[1]}</strong></div>`).join('')}</div>`}${d.maintenanceUntil>Date.now()/1000?`<div class="notice">Alerts silenced for maintenance until ${esc(new Date(d.maintenanceUntil*1000).toLocaleString())}.</div>`:''}<p class="metric-note">Last report: ${age(d.lastSeen)} · ${esc(d.source||'Not connected')}</p>${d.connectionError?`<p class="error">${esc(d.connectionError)}</p>`:''}${printerSupplies(d)}<div class="actions"><button class="btn" data-role="write" onclick="editDevice(${id})">Edit device</button><button class="btn primary" data-role="admin" onclick="enroll(${id})">Connect agent</button><button class="btn" data-role="write" onclick="checkDevice(${id})">Test connection</button><button class="btn" data-role="admin" onclick="connectionForm(${id})">API / SNMP connection</button>${d.integration?`<button class="btn" data-role="write" onclick="pollDevice(${id})">Poll now</button>${!['snmp','printer'].includes(d.integration.kind)?`<button class="btn" data-role="admin" onclick="discoverDevice(${id})">Discover resources</button>`:''}`:''}${d.integration?.kind==='printer'?'':`<button class="btn" data-role="write" onclick="controls(${id})">Manage device</button>`}<button class="btn" data-role="write" onclick="maintenanceForm(${id})">Maintenance</button><button class="btn" data-role="write" onclick="removeDevice(${id})">Delete</button></div>${d.integration?.kind==='printer'?'':`<h2 class="section">CPU history</h2><div id="history" class="empty">Loading measurements…</div><p class="metric-note">Measurements are retained for 30 days. History shows the latest 100 reports.</p>`}`);applyRole();if(d.integration?.kind==='printer')return;try{let samples=await api('/api/history/'+id);if(!$('#history'))return;if(!samples.length){$('#history').textContent='No measurements yet. Connect an agent or configure an API / SNMP connection.';return}let values=samples.slice().reverse().filter(x=>x.cpu!=null);if(!values.length){$('#history').textContent='This device does not expose CPU measurements.';return}let points=values.map((x,i)=>`${values.length===1?150:i/(values.length-1)*300},${80-x.cpu*.75}`).join(' ');$('#history').innerHTML=`<svg class="spark" viewBox="0 0 300 90" role="img" aria-label="Measured CPU usage"><polyline points="${points}" fill="none" stroke="#4367e9" stroke-width="2"/>${values.length===1?`<circle cx="150" cy="${80-values[0].cpu*.75}" r="3" fill="#4367e9"/>`:''}</svg><span class="metric-note">${esc(new Date(values[0].time*1000).toLocaleTimeString())} — ${esc(new Date(values.at(-1).time*1000).toLocaleTimeString())}</span>`}catch(e){toast(e.message)}}
function removeDevice(id){if(confirm('Delete this device, its agent credential, metrics, and incidents?'))mutate(s=>{s.devices=s.devices.filter(d=>d.id!==id)})}
async function checkDevice(id){try{let r=await api('/api/check','POST',{id});toast(r.reachable?`Connection successful on port ${r.port} (${r.latencyMs} ms). This does not enroll an agent.`:`Cannot connect on port ${r.port}. Check the device and network.`)}catch(e){toast(e.message)}}
async function enroll(id){if(!confirm('Generate a new agent credential? Any existing agent for this device will need the new credential.'))return;try{let r=await api('/api/enroll','POST',{id});modal('<h1>Connect Linux agent</h1><p>Run these commands as root inside the Linux device you selected. The credential is shown once and grants permission to submit metrics for this device only.</p><pre id="installCommand"></pre><label class="formlabel"><input id="agentControl" type="checkbox"> Enable reboot and package update checks on this device</label><button class="btn" id="copyInstall">Copy commands</button><p class="metric-note">Reports start within a minute. Device controls are disabled by default. Set allowControl to true in /etc/bitwise-agent.json and restart the agent to enable reboot and update checks. Use this HTTP endpoint only on your trusted network; remote deployments need HTTPS.</p>');let config=JSON.stringify({server:location.origin,token:r.token,interval:60,allowControl:false});let command=`install -d -m 755 /opt/bitwise-agent\npython3 -c 'from urllib.request import urlretrieve; urlretrieve("${location.origin}/agent.py", "/opt/bitwise-agent/agent.py")'\ncat > /etc/bitwise-agent.json <<'CONFIG'\n${config}\nCONFIG\nchmod 600 /etc/bitwise-agent.json\ncat > /etc/systemd/system/bitwise-agent.service <<'SERVICE'\n[Unit]\nDescription=Bitwise Control Device integrations\nAfter=network-online.target\nWants=network-online.target\n[Service]\nExecStart=/usr/bin/python3 /opt/bitwise-agent/agent.py\nRestart=always\nRestartSec=15\nNoNewPrivileges=yes\nProtectSystem=strict\nProtectHome=yes\nPrivateTmp=yes\n[Install]\nWantedBy=multi-user.target\nSERVICE\nsystemctl daemon-reload\nsystemctl enable --now bitwise-agent`;$('#installCommand').textContent=command;$('#agentControl').onchange=e=>{$('#installCommand').textContent=command.replace('\"allowControl\":false','\"allowControl\":'+e.target.checked)};$('#copyInstall').onclick=async()=>{try{await navigator.clipboard.writeText($('#installCommand').textContent);toast('Commands copied.')}catch{toast('Select and copy the commands above.')}}}catch(e){toast(e.message)}}
function passwordForm(){modal('<h1>Change password</h1><form id="passwordForm"><label class="formlabel" for="currentPassword">Current password</label><input id="currentPassword" class="field" type="password" name="current" autocomplete="current-password" required><label for="newPassword">New password</label><input id="newPassword" class="field" type="password" name="password" autocomplete="new-password" minlength="12" maxlength="1024" required><label for="confirmPassword">Confirm new password</label><input id="confirmPassword" class="field" type="password" autocomplete="new-password" required><button class="btn primary">Change password</button></form>');$('#passwordForm').onsubmit=async e=>{e.preventDefault();if($('#newPassword').value!==$('#confirmPassword').value)return toast('Passwords do not match.');try{await api('/api/password','POST',Object.fromEntries(new FormData(e.target)));closePanel();toast('Password changed.')}catch(e){toast(e.message)}}}
function exportLogs(){let csv=[['Time','User','Action','Device'],...state.logs.map(l=>[l.time,l.actor||'system',l.action,l.device])].map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');let a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='bitwise-activity.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importInventory(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{let file=input.files[0];if(file.size>2000000)throw Error('Inventory file is too large.');let data=JSON.parse(await file.text());if(!Array.isArray(data.companies)||!Array.isArray(data.devices))throw Error('Invalid inventory backup.');if(confirm('Replace your inventory with this backup? Removed devices will lose their agent credentials and history.'))await mutate(s=>{s.companies=data.companies;s.devices=data.devices})}catch(e){toast(e.message)}};input.click()}
async function boot(){try{await refresh();let old;try{old=JSON.parse(sessionStorage.getItem('bitwise-control-clean-v2'))}catch{}if(old?.devices?.length&&!state.devices.length){if(confirm('Import the devices you previously added in this browser into the server database?')){await mutate(s=>{s.companies=old.companies;s.devices=old.devices.map(d=>({...d,port:d.port||22}))});if(state.devices.length)sessionStorage.removeItem('bitwise-control-clean-v2')}}localStorage.removeItem('bitwise-control-v1')}catch(e){toast(e.message)}}
setInterval(async()=>{if(busy||!$('#drawer').classList.contains('hidden')||document.activeElement?.tagName==='INPUT')return;try{await refresh()}catch(e){toast(e.message)}},30000);boot();

function connectionForm(id){let device=state.devices.find(d=>d.id===id),saved=device.integration||{},initial=saved.kind||(device.type==='Printer'?'printer':/proxmox/i.test(device.platform)?'proxmox':/mikrotik|routeros/i.test(device.platform)?'mikrotik':/unifi/i.test(device.platform)?'unifi':'snmp');modal(`<h1>Device connection</h1><p>${esc(device.name)}</p><label for="adapterKind">Connection method</label><select id="adapterKind" class="field">${[['proxmox','Proxmox VE API'],['mikrotik','MikroTik RouterOS 7 REST'],['unifi','UniFi Network API'],['snmp','SNMPv3'],['printer','Printer supplies (SNMPv3)']].map(([v,n])=>`<option value="${v}" ${initial===v?'selected':''}>${n}</option>`).join('')}</select><form id="connectionForm"><div id="connectionFields"></div><button class="btn primary">Save connection</button><button class="btn" type="button" id="discoverConnection">Discover targets</button><div id="connectionDiscovery"></div><button class="btn" type="button" id="removeConnection">Disconnect</button></form>`);
 function fields(){let kind=$('#adapterKind').value,c=saved.kind===kind?saved:{};let f=(key,label,value='',secret=false)=>`<label class="formlabel" for="cfg-${key}">${label}</label><input id="cfg-${key}" class="field" name="${key}" type="${secret?'password':'text'}" ${secret?'autocomplete="new-password"':''} value="${secret?'':esc(c[key]??value)}" placeholder="${secret&&c.credentialsConfigured?'Leave blank to keep existing credential':''}">`;let html='';if(!['snmp','printer'].includes(kind)){html+=f('url',kind==='unifi'?'Controller API base URL':'Server HTTPS address',kind==='proxmox'?`https://${device.ip}:8006`:kind==='unifi'?`https://${device.ip}/proxy/network/integration/v1`:`https://${device.ip}`);html+='<p class="metric-note">Certificates are verified. For a private CA, paste its certificate below.</p><label for="cfg-caPem">CA certificate PEM (optional)</label><textarea id="cfg-caPem" class="field" name="caPem" rows="3">'+esc(c.caPem||'')+'</textarea>'}
 if(kind==='proxmox')html+=f('tokenId','API token ID (user@realm!token)')+f('tokenSecret','API token secret','',true)+f('node','Proxmox node name')+`<label for="cfg-target">Target</label><select id="cfg-target" class="field" name="target">${[['node','Proxmox host'],['lxc','LXC container'],['qemu','Virtual machine']].map(([v,n])=>`<option value="${v}" ${c.target===v?'selected':''}>${n}</option>`).join('')}</select>`+f('vmid','VM/container ID (guests only)');
 if(kind==='mikrotik')html+=f('username','REST username')+f('password','REST password','',true);
 if(kind==='unifi')html+=f('apiKey','API key','',true)+f('siteId','Site UUID')+f('deviceId','Adopted device UUID')+'<p class="metric-note">Requires the official UniFi Network Integration API. The base URL ends with /integration/v1.</p>';
 if(['snmp','printer'].includes(kind))html+=f('host','Device IPv4 address or hostname',device.ip)+f('port','SNMP UDP port','161')+f('contextName','SNMP context name (optional; HP may require Jetdirect)')+f('username','SNMPv3 security username')+f('authPassword','SHA authentication passphrase','',true)+f('privPassword','AES privacy passphrase','',true)+'<p class="metric-note">SNMPv3 uses SHA authentication and AES encryption. Readings depend on the device’s MIB support.</p>';
 if(kind==='snmp')html+=f('temperatureOid','Temperature numeric OID (optional)')+f('temperatureDivisor','Temperature divisor','1');
 if(kind==='printer')html+=`<label class="formlabel" for="cfg-supplyThreshold">Low supply warning (% remaining; 0 disables)</label><input id="cfg-supplyThreshold" class="field" name="supplyThreshold" type="number" min="0" max="100" step="1" required value="${esc(c.supplyThreshold??20)}">`+'<p class="metric-note">Read-only Printer-MIB monitoring. Warnings apply to consumed supplies at or below this threshold. Unknown levels stay unavailable. Enable SNMPv3 on the printer.</p>';
 html+=kind==='printer'?'<input type="hidden" name="allowControl"><p class="metric-note">Saving this connection replaces any Linux agent credential for this device.</p>':`<label class="formlabel"><input type="checkbox" name="allowControl" ${c.allowControl?'checked':''}> Enable device management actions</label><p class="metric-note">Grant write permissions only if you intend to use reboot, configuration, upgrade, or PoE actions. Saving an API connection replaces any Linux agent credential for this inventory entry.</p>`;$('#connectionFields').innerHTML=html;$('#discoverConnection').classList.toggle('hidden',['snmp','printer'].includes(kind))}
 fields();$('#adapterKind').onchange=fields;$('#connectionForm').onsubmit=async e=>{e.preventDefault();let form=e.target,config=Object.fromEntries(new FormData(form));config.kind=$('#adapterKind').value;config.allowControl=form.elements.allowControl.checked;if(config.kind==='proxmox'){if(config.vmid)config.vmid=+config.vmid;else delete config.vmid}if(['snmp','printer'].includes(config.kind)){config.port=+config.port;if(config.kind==='snmp')config.temperatureDivisor=+config.temperatureDivisor}if(config.kind==='printer'){config.supplyThreshold=+config.supplyThreshold;config.allowControl=false}let button=form.querySelector('button');button.disabled=true;try{await api('/api/integration','POST',{id,config});await refresh();closePanel();toast('Connection saved. Poll now to verify it.')}catch(e){toast(e.message)}finally{button.disabled=false}};$('#discoverConnection').onclick=async()=>{let config=Object.fromEntries(new FormData($('#connectionForm')));config.kind=$('#adapterKind').value;config.allowControl=false;let scope=config.kind==='unifi'&&!config.siteId?'sites':'devices';try{let result=await api('/api/discover','POST',{id,config,scope}),items=Array.isArray(result)?result:result.data||[];$('#connectionDiscovery').innerHTML='<h2 class="section">Discovered targets</h2>'+items.map((item,i)=>`<div class="alert"><div><strong>${esc(item.name||item.id||item.node||item['.id'])}</strong><p>${esc(item.type||'')} ${esc(item.vmid||item.id||'')}</p><button class="btn" type="button" data-pick-target="${i}">Use target</button></div></div>`).join('');document.querySelectorAll('[data-pick-target]').forEach(el=>el.onclick=()=>{let item=items[+el.dataset.pickTarget];if(config.kind==='proxmox'){$('#cfg-node').value=item.node||item.name;$('#cfg-target').value=['lxc','qemu'].includes(item.type)?item.type:'node';$('#cfg-vmid').value=item.vmid||''}if(config.kind==='unifi'){$(scope==='sites'?'#cfg-siteId':'#cfg-deviceId').value=item.id}toast('Target selected. Save the connection to begin polling.');$('#connectionDiscovery').innerHTML=''})}catch(e){toast(e.message)}};$('#removeConnection').onclick=async()=>{if(!confirm('Remove this API connection and its saved credentials?'))return;try{await api('/api/integration','POST',{id,config:null});await refresh();closePanel();toast('Connection removed.')}catch(e){toast(e.message)}}}
async function pollDevice(id){toast('Polling device…');try{state=await api('/api/poll','POST',{id});render();detail(id);toast('Device measurements updated.')}catch(e){toast(e.message);await refresh()}}
async function discoverDevice(id){try{let result=await api('/api/discover','POST',{id});modal('<h1>Discovered resources</h1><p>Use the node, VM/container, site, or device identifiers below when configuring inventory connections.</p><pre id="discoveryResult"></pre>');$('#discoveryResult').textContent=JSON.stringify(result,null,2)}catch(e){toast(e.message)}}
async function controls(id){let d=state.devices.find(d=>d.id===id),kind=d.integration?.kind||'linux';if(kind==='printer')return toast('Printer monitoring is read-only.');let actions=({linux:[['upgrade_check','Check Ubuntu updates'],['reboot','Reboot device']],proxmox:[['reboot','Reboot target'],...(d.integration.target==='node'?[['upgrade_check','Check available updates']]:[['start','Start guest'],['shutdown','Shut down guest'],['configure','Set guest CPU / memory']]),['config_backup','Read configuration']],mikrotik:[['reboot','Reboot router'],['upgrade_check','Check RouterOS updates'],['upgrade','Install RouterOS update'],['poe','Set port PoE'],['config_backup','Export configuration']],unifi:[['reboot','Restart device'],['poe_cycle','Power-cycle PoE port'],['config_backup','Read device details']],snmp:[['poe','Set standard SNMP PoE']]})[kind];modal(`<h1>Device management</h1><p>${esc(d.name)} · ${esc(d.ip)}</p><p class="metric-note">Actions run on the connected target and are recorded in the activity log. ${kind==='linux'?'The agent must have controls enabled.':'Enable controls in the connection settings before using these actions.'}</p><form id="controlForm"><label for="controlAction">Action</label><select id="controlAction" class="field">${actions.map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select><div id="actionFields"></div><button class="btn primary">Run action</button></form><h2 class="section">Recent operations</h2><div id="jobs" class="empty">Loading…</div>`);
 function fields(){let action=$('#controlAction').value,html='';if(action==='configure')html='<label for="controlMemory">Memory (MiB)</label><input class="field" id="controlMemory" type="number" min="1" max="1048576"><label for="controlCores">CPU cores</label><input class="field" id="controlCores" type="number" min="1" max="256">';if(action==='poe'||action==='poe_cycle'){html=kind==='mikrotik'?'<label for="controlPort">PoE interface</label><select class="field" id="controlPort">'+(d.ports||[]).map(p=>`<option value="${esc(p['.id'])}">${esc(p.name||p['.id'])} · ${esc(p['poe-out'])}</option>`).join('')+'</select>':'<label for="controlPort">Port number</label><input class="field" id="controlPort" type="number" min="1" max="1024" required>';if(kind==='snmp')html+='<label for="controlGroup">PSE group</label><input class="field" id="controlGroup" type="number" value="1" min="1" max="1024">';if(action==='poe')html+='<label for="controlMode">PoE mode</label><select class="field" id="controlMode">'+(kind==='mikrotik'?['off','auto-on','forced-on']:['off','on']).map(m=>`<option>${m}</option>`).join('')+'</select>'}$('#actionFields').innerHTML=html}
 fields();$('#controlAction').onchange=fields;$('#controlForm').onsubmit=async e=>{e.preventDefault();let action=$('#controlAction').value,args={};if(action==='configure'){if($('#controlMemory').value)args.memory=+$('#controlMemory').value;if($('#controlCores').value)args.cores=+$('#controlCores').value}if(action==='poe'||action==='poe_cycle'){args.port=kind==='mikrotik'?$('#controlPort').value:+$('#controlPort').value;if($('#controlMode'))args.mode=$('#controlMode').value;if($('#controlGroup'))args.group=+$('#controlGroup').value}if(!confirm(`${action.replaceAll('_',' ')} on ${d.name} (${d.ip})? This action contacts the real device.`))return;let button=e.target.querySelector('button');button.disabled=true;try{let r=await api('/api/action','POST',{id,action,arguments:args});toast('Operation '+r.status+'.');await showJobs(id);if(r.result){let pre=document.createElement('pre');pre.textContent=JSON.stringify(r.result,null,2);$('#jobs').prepend(pre)}}catch(e){toast(e.message)}finally{button.disabled=false}};showJobs(id)}
async function showJobs(id){try{let jobs=await api('/api/jobs/'+id);if(!$('#jobs'))return;$('#jobs').innerHTML=jobs.map(j=>`<div class="alert"><div><strong>${esc(j.action)} · ${esc(j.status)}</strong><p>${esc(new Date(j.created*1000).toLocaleString())}</p>${j.result?`<pre>${esc(JSON.stringify(j.result,null,2))}</pre>`:''}</div></div>`).join('')||'No management operations yet.'}catch(e){toast(e.message)}}

function deliveryStatus(){return `<div data-role="admin"><h3>Recent deliveries</h3>${(state.notificationStatus||[]).map(n=>`<p class="metric-note">${esc(n.channel||'Notification')} · ${esc(n.status)} · ${n.attempts} attempts<br>${esc(n.subject)}</p>`).join('')||'<p class="metric-note">No notifications queued yet.</p>'}</div>`}
function monitoringForm(){let current=state.monitoring||{rules:{cpu:90,memory:90,disk:90,temperature:70,offlineSeconds:180},delivery:{mode:'none'}},r=current.rules,d=current.delivery;modal(`<h1>Monitoring and alerts</h1><form id="monitoringForm"><h2 class="section">Thresholds</h2><p class="metric-note">Set a resource threshold to 0 to disable that rule. Recovery closes the incident automatically.</p>${[['cpu','CPU (%)'],['memory','Memory (%)'],['disk','Disk (%)'],['temperature','Temperature (°C)'],['offlineSeconds','Missing-report timeout (seconds)']].map(([k,n])=>`<label class="formlabel" for="rule-${k}">${n}</label><input class="field" id="rule-${k}" name="${k}" type="number" min="${k==='offlineSeconds'?60:0}" max="${k==='offlineSeconds'?3600:200}" value="${r[k]}" required>`).join('')}<h2 class="section">Notification delivery</h2><label class="formlabel" for="deliveryMode">Channel</label><select class="field" id="deliveryMode" name="mode">${[['none','Disabled'],['email','Email (SMTP with TLS)'],['discord','Discord'],['both','Discord + SMTP email'],['webhook','HTTPS webhook']].map(([v,n])=>`<option value="${v}" ${d.mode===v?'selected':''}>${n}</option>`).join('')}</select><div id="deliveryFields"></div><button class="btn primary">Save monitoring settings</button><button class="btn" type="button" id="testNotifications">Send test notification</button><p class="metric-note">Test uses the values above and sends one message per selected channel. It does not save settings or retry automatically.</p><div id="testNotificationResults" role="status" aria-live="polite"></div></form>`);
 function fields(){let mode=$('#deliveryMode').value;let f=(k,n,value='',secret=false)=>`<label class="formlabel" for="notify-${k}">${n}</label><input class="field" id="notify-${k}" name="${k}" type="${secret?'password':'text'}" value="${secret?'':esc(d[k]??value)}" ${secret?'autocomplete="new-password"':''} placeholder="${secret&&d.credentialsConfigured?'Leave blank to keep saved credential':''}">`;let html='';if(mode==='none')html='<p class="metric-note">Incidents remain visible inside the app. No messages will be sent.</p>';if(['email','both'].includes(mode))html+='<h2 class="section">SMTP email</h2>'+f('smtpHost','SMTP server')+f('smtpPort','SMTP port (587 STARTTLS or 465 TLS)','587')+f('smtpUser','SMTP username')+f('smtpPassword','SMTP password','',true)+f('sender','From email address')+f('recipient','Recipient email address');if(['discord','both'].includes(mode))html+='<h2 class="section">Discord</h2>'+f('discordUrl','Discord webhook URL','',true)+'<p class="metric-note">In your Discord server, open the destination channel settings → Integrations → Webhooks. Create a webhook and paste its URL here.</p>';if(mode==='webhook')html+=f('webhookUrl','Webhook HTTPS URL','',true)+f('webhookToken','Bearer token (optional)','',true);if(mode!=='none'){for(let [key,label] of [['reminderMinutes','Repeat unresolved alert reminders'],['summaryMinutes','Send status summaries (including healthy devices)']])html+=`<label class="formlabel" for="notify-${key}">${label}</label><select class="field" id="notify-${key}" name="${key}">${[[0,'Disabled'],[5,'Every 5 minutes'],[10,'Every 10 minutes']].map(([v,n])=>`<option value="${v}" ${Number(d[key]||0)===v?'selected':''}>${n}</option>`).join('')}</select>`}if(mode!=='none')html+='<p class="metric-note">Saving enables messages for new incidents and recoveries. Each channel retries independently up to five times. Open alerts repeat only when reminders are enabled.</p>';$('#deliveryFields').innerHTML=html}

 function payload(){let form=Object.fromEntries(new FormData($('#monitoringForm'))),rules={};for(let k of ['cpu','memory','disk','temperature','offlineSeconds']){rules[k]=+form[k];delete form[k]}if(form.smtpPort)form.smtpPort=+form.smtpPort;for(let k of ['reminderMinutes','summaryMinutes'])if(k in form)form[k]=+form[k];return {rules,delivery:form}}
 fields();$('#deliveryMode').onchange=()=>{fields();$('#testNotificationResults').textContent=''};$('#testNotifications').onclick=async()=>{let buttons=[...$('#monitoringForm').querySelectorAll('button')],result=$('#testNotificationResults');buttons.forEach(b=>b.disabled=true);result.textContent='Sending test notification…';try{let response=await api('/api/monitoring/test','POST',payload());result.innerHTML=response.results.map(r=>`<p class="${r.status==='failed'?'error':'metric-note'}"><strong>${esc(r.channel==='email'?'SMTP email':r.channel==='discord'?'Discord':'Webhook')}: ${r.status==='sent'?'Sent':'Failed'}</strong><br>${esc(r.message)}</p>`).join('')}catch(e){result.textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}};$('#monitoringForm').onsubmit=async e=>{e.preventDefault();let form=Object.fromEntries(new FormData(e.target)),rules={};for(let k of ['cpu','memory','disk','temperature','offlineSeconds']){rules[k]=+form[k];delete form[k]}if(form.smtpPort)form.smtpPort=+form.smtpPort;for(let k of ['reminderMinutes','summaryMinutes'])if(k in form)form[k]=+form[k];let button=e.target.querySelector('button');button.disabled=true;try{await api('/api/monitoring','POST',{rules,delivery:form});await refresh();closePanel();toast('Monitoring settings saved.')}catch(e){toast(e.message)}finally{button.disabled=false}}}

function applyRole(){let u=state.currentUser||{username:'admin',role:'admin'},role=u.role;document.querySelectorAll('[data-role]').forEach(el=>el.classList.toggle('hidden',el.dataset.role==='admin'?role!=='admin':role==='viewer'));$('#addDevice').disabled=role==='viewer';$('.bottom').innerHTML=`<span class="avatar">${esc(u.username.slice(0,2).toUpperCase())}</span> &nbsp; ${esc(u.username)}<p style="margin-left:42px;font-size:10px">${esc(role)} account</p>`}
let accounts=[];
async function usersForm(){try{accounts=await api('/api/users');modal('<h1>User access</h1><p>Administrators manage all companies. Operators can edit devices and run enabled controls in assigned companies. Viewers have read-only access.</p><button class="btn primary" onclick="userEditor()">Add user</button><div id="accountList" class="section"></div>');$('#accountList').innerHTML=accounts.map((u,i)=>`<div class="alert"><div><strong>${esc(u.username)}</strong><p>${esc(u.role)} · ${u.enabled?'Enabled':'Disabled'}</p><button class="btn" data-edit-user="${i}">Edit access</button></div></div>`).join('')||'<p>No additional users yet.</p>';document.querySelectorAll('[data-edit-user]').forEach(el=>el.onclick=()=>userEditor(accounts[+el.dataset.editUser]))}catch(e){toast(e.message)}}
function userEditor(user){let u=user||{username:'',role:'viewer',companies:[],enabled:true};modal(`<h1>${user?'Edit user':'Add user'}</h1><form id="userForm"><label class="formlabel" for="userName">Username</label><input id="userName" class="field" name="username" pattern="[A-Za-z0-9_.-]{3,64}" required value="${esc(u.username)}" ${user?'readonly':''}><label for="userPassword">${user?'New password (leave blank to keep current)':'Initial password'}</label><input class="field" id="userPassword" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" ${user?'':'required'}><label for="userRole">Role</label><select class="field" id="userRole" name="role">${['viewer','operator','admin'].map(role=>`<option ${u.role===role?'selected':''}>${role}</option>`).join('')}</select><h2 class="section">Company access</h2><p class="metric-note">Administrators can access every company. Assign companies for operators and viewers. Recheck assignments after renaming a company.</p>${state.companies.map((c,i)=>`<label class="formlabel"><input type="checkbox" name="companies" value="${i}" ${u.companies.includes(c)?'checked':''}> ${esc(c)}</label>`).join('')||'<p class="metric-note">Create companies before assigning access.</p>'}<label class="formlabel"><input type="checkbox" id="userEnabled" ${u.enabled?'checked':''}> Account enabled</label><button class="btn primary section">Save user</button></form>`);$('#userForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),body={username:f.get('username'),password:f.get('password'),role:f.get('role'),companies:f.getAll('companies').map(i=>state.companies[+i]),enabled:$('#userEnabled').checked};try{await api('/api/users','POST',body);toast('User access saved. Their existing sessions have been revoked.');usersForm()}catch(e){toast(e.message)}}}

function maintenanceForm(id){let d=state.devices.find(d=>d.id===id);modal(`<h1>Maintenance window</h1><p>${esc(d.name)}</p><p>Monitoring continues during maintenance. Alerts and notifications for this device are silenced until the window ends.</p><form id="maintenanceForm"><label for="maintenanceMinutes">Duration (minutes)</label><input class="field" id="maintenanceMinutes" type="number" min="1" max="10080" required value="60"><button class="btn primary">Start maintenance</button><button type="button" class="btn" id="endMaintenance">End maintenance</button></form>`);$('#maintenanceForm').onsubmit=e=>{e.preventDefault();let until=Date.now()/1000+Number($('#maintenanceMinutes').value)*60;mutate(s=>{s.devices.find(d=>d.id===id).maintenanceUntil=until})};$('#endMaintenance').onclick=()=>mutate(s=>{s.devices.find(d=>d.id===id).maintenanceUntil=0})}
